import 'dart:async';import 'dart:convert';import 'dart:io';
import 'package:shared_preferences/shared_preferences.dart';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/advanced_theme.dart';import 'package:flutter_core/workspace.dart';import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeTextButton;
List<Map<String,dynamic>> fixtures()=>(jsonDecode(File('test/advanced_theme/fixtures/web.json').readAsStringSync()) as List).cast<Map<String,dynamic>>();
void main(){
 test('96 themes match four-region colors, derived shades, schema visibility and workspace projection',(){final out=<Object>[];for(final c in fixtures()){final theme=AdvancedTheme.fromJson(c['theme']),fields=ThemeField.parse(c['schema'],(c['ids'] as List).cast<String>());for(final region in themeRegions){final p=theme.region(region),data=advancedThemeData(ThemeData(),theme,region),fg=data.textButtonTheme.style!.foregroundColor!.resolve(<WidgetState>{})!;final hex='#${fg.toARGB32().toRadixString(16).substring(2)}';expect(themeContrast(hex,p['surface']! as String),greaterThanOrEqualTo(4.5));expect(themeContrast(hex,p['background']! as String),greaterThanOrEqualTo(4.5));}final actual={'theme':theme.toJson(),'previews':{for(final r in themeRegions)r:themePalettePreview(theme.region(r))},'fields':fields.map((f)=>f.toJson()).toList(),'visible':fields.where((f)=>f.visible(theme)).map((f)=>f.id).toList(),'workspace':theme.workspace(WorkspaceLayout.defaults(['note'])).toJson()};expect(actual,c['expected']);out.add(actual);}File('test/advanced_theme/fixtures/native.json').writeAsStringSync(jsonEncode(out));expect(()=>AdvancedTheme.defaults().patch('tokens.fontFamily','url(evil)'),throwsFormatException);expect(ThemeField.parse(fixtures().first['schema'],[]),isEmpty);});
 test('legacy personal JSON and canonical v1 XML remain separate lossless contracts',(){final f=jsonDecode(File('test/advanced_theme/fixtures/legacy.json').readAsStringSync()) as Map;expect(importThemeDocument(jsonEncode(f['theme']))['value'],f['theme']);expect(importThemeDocument(f['xml'] as String)['value'],f['layout']);for(final xml in [(f['xml'] as String).replaceFirst('version="1"','version="2"'),'<!DOCTYPE x>'+ (f['xml'] as String),(f['xml'] as String).replaceFirst('<Theme','<Theme role="admin"')]){expect(()=>legacyLayoutXml(xml),throwsFormatException);}});
 test('scoped storage CRUD is atomic, rejects duplicates and ignores late actor writes',()async{SharedPreferences.setMockInitialValues({});final preferences=await SharedPreferences.getInstance();final saved=AdvancedThemeController.preferences(scope:'saved-actor',preferences:preferences);await saved.initialize();await saved.apply(AdvancedTheme.defaults());saved.dispose();final restored=AdvancedThemeController.preferences(scope:'saved-actor',preferences:preferences);await restored.initialize();expect(restored.active!.toJson(),AdvancedTheme.defaults().toJson());restored.dispose();final isolated=AdvancedThemeController.preferences(scope:'different-actor',preferences:preferences);await isolated.initialize();expect(isolated.active,isNull);isolated.dispose();final store=<String,String>{};var fail=false;final a=AdvancedThemeController(scope:'[tenant,actor,role,data]',read:(k)async=>store[k],write:(k,v)async{if(fail)throw StateError('Storage unavailable');store[k]=v;});await a.initialize();final t=AdvancedTheme.defaults(),id=await a.save(t);await a.rename(id,'Renamed');final copy=await a.duplicate(id,'Copy');expect(a.items.length,2);await a.apply(t);final before=jsonEncode(a.current);fail=true;await expectLater(a.remove(copy),throwsStateError);expect(jsonEncode(a.current),before);fail=false;await expectLater(a.duplicate(id,'Copy'),throwsFormatException);await a.remove(copy);await a.apply(null);expect(a.active,isNull);a.dispose();final gate=Completer<void>();final old=AdvancedThemeController(scope:'old',read:(k)async=>null,write:(k,v)async{await gate.future;store[k]=v;});await old.initialize();final work=old.apply(t);old.dispose();gate.complete();await expectLater(work,throwsStateError);expect(store.keys.every((k)=>!k.endsWith(':new')),true);});
 testWidgets('schema forms preview, CRUD, copy, conditional controls and reset preserve business content',(tester)async{
  tester.view.physicalSize=const Size(1500,1000);tester.view.devicePixelRatio=1;addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);
  final c=AdvancedThemeController(scope:'actor',read:(k)async=>null,write:(k,v)async{});await c.initialize();addTearDown(c.dispose);final f=fixtures().first,fields=ThemeField.parse(f['schema'],(f['ids'] as List).cast<String>()).where((f)=>['name','layout.container','layout.maxWidth'].contains(f.path)).toList();String? copied;AdvancedTheme? applied;
  final labels={for(final key in ['saved','preview','configuration','apply','save','update','rename','duplicate','remove','reset','copy','import','export','success','error','empty'])key:key};final options={for(final key in ['primary','secondary','success','warning','error','info','fullwidth','boxed','content'])key:key};
  await tester.pumpWidget(MaterialApp(home:Scaffold(body:Column(children:[const TextField(key:ValueKey('business')),Expanded(child:PrimeAdvancedThemeEditor(controller:c,fields:fields,labels:labels,optionLabels:options,regionLabels:{for(final r in themeRegions)r:r},padding:const EdgeInsets.all(8),spacing:8,onApply:(t)=>applied=t,onLegacy:(_){},copyText:(text)async{copied=text;},download:(_)async{},pickText:()async=>null))]))));await tester.pumpAndSettle();await tester.enterText(find.byKey(const ValueKey('business')),'Unsaved business');final name=find.byKey(ValueKey('theme-field-${fields.firstWhere((f)=>f.path=='name').id}'));await tester.enterText(name,'Named');await tester.ensureVisible(find.byKey(const ValueKey('theme-action-save')));await tester.tap(find.byKey(const ValueKey('theme-action-save')));await tester.pumpAndSettle();expect(c.items.length,1);await tester.tap(find.byKey(const ValueKey('theme-action-apply')));await tester.pumpAndSettle();expect(applied!.name,'Named');await tester.tap(find.byKey(const ValueKey('theme-action-copy')));await tester.pumpAndSettle();expect(jsonDecode(copied!)['version'],2);await tester.tap(find.byKey(const ValueKey('theme-action-reset')));await tester.pumpAndSettle();expect(c.active,isNull);expect(find.text('Unsaved business'),findsOneWidget);expect(tester.takeException(),isNull);
 });
 testWidgets('actor replacement rejects pending imports and detached editor callbacks',(tester)async{
  final old=AdvancedThemeController(scope:'old-actor',read:(k)async=>null,write:(k,v)async{}),next=AdvancedThemeController(scope:'new-actor',read:(k)async=>null,write:(k,v)async{});await old.initialize();await next.initialize();addTearDown(old.dispose);addTearDown(next.dispose);final gate=Completer<String?>();
  final f=fixtures().first,fields=ThemeField.parse(f['schema'],(f['ids'] as List).cast<String>()).where((f)=>f.path=='name').toList();final labels={for(final key in ['saved','preview','configuration','apply','save','update','rename','duplicate','remove','reset','copy','import','export','success','error','empty'])key:key},options={for(final key in ['primary','secondary','success','warning','error','info'])key:key};
  Future<void> mount(AdvancedThemeController c)async{await tester.pumpWidget(MaterialApp(home:Scaffold(body:PrimeAdvancedThemeEditor(controller:c,fields:fields,labels:labels,optionLabels:options,regionLabels:{for(final r in themeRegions)r:r},padding:const EdgeInsets.all(8),spacing:8,onApply:(_){},onLegacy:(_){},copyText:(_)async{},download:(_)async{},pickText:()=>gate.future))));await tester.pumpAndSettle();}
  await mount(old);final detached=tester.widget<PrimeTextButton>(find.byKey(const ValueKey('theme-action-apply'))).onPressed!;await tester.ensureVisible(find.byKey(const ValueKey('theme-action-import')));await tester.tap(find.byKey(const ValueKey('theme-action-import')));await tester.pump();await mount(next);gate.complete(AdvancedTheme.defaults().patch('name','Old actor import').exportJson());await tester.pumpAndSettle();detached();await tester.pumpAndSettle();expect(old.active,isNull);expect(next.active,isNull);expect(find.textContaining('Old actor import'),findsNothing);expect(tester.widget<PrimeTextButton>(find.byKey(const ValueKey('theme-action-apply'))).onPressed,isNotNull);expect(tester.takeException(),isNull);
 });

}
